xql_query:
// ============================================================
// Rule: FGT_BGP Communication Failure
// Vendor: Fortigate
// Objective:
// Detect activity associated with FGT_BGP Communication Failure.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================

dataset = fortinet_fortigate_raw 
//| filter msg contains "BGP"
| filter (cat = """event:router""")
| filter msg contains "Down"

| fields _final_reporting_device_ip, _reporting_device_name, msg
